var e={profile:{name:"Daniela Cede\xF1o",credentials:"Nutricionista \xB7 Entrenadora personal",introduction:"Te acompa\xF1o a construir h\xE1bitos que caben en tu vida y un cuerpo que se siente fuerte, sin planes imposibles ni culpas.",biography:"Soy Daniela, nutricionista y entrenadora. Trabajo desde la escucha, la evidencia y el movimiento posible. Empezamos por entender tu punto de partida; despu\xE9s construimos lo que puedes sostener.",highlights:[{title:"100%",text:"personalizado"},{title:"Online",text:"y presencial"},{title:"Real",text:"para tu rutina"}],review:"draft",contact:{email:"",instagram:"",whatsapp:""},timezone:""},services:[{id:"nutrition",title:"Consulta nutricional",description:"Evaluaci\xF3n, objetivos y un plan flexible construido alrededor de tus horarios, gustos y contexto.",benefits:["Consulta inicial de 60 min","Plan y recetario personal","Seguimiento quincenal"],modalities:["online","presencial"],durationMinutes:60,bookingType:"nutrition",review:"draft",cssClass:"service-nutrition",symbol:"\u25D2"},{id:"training",title:"Entrenamiento personal",description:"Sesiones funcionales progresivas para ganar fuerza, confianza y autonom\xEDa al moverte.",benefits:["Presencial u online","Rutinas adaptadas","Correcci\xF3n en tiempo real"],modalities:["online","presencial"],durationMinutes:null,bookingType:"training",review:"draft",cssClass:"service-training",symbol:"\u2301"},{id:"integral",title:"Proceso integral",description:"Nutrici\xF3n y entrenamiento en un mismo programa para avanzar con una estrategia coherente.",benefits:["Plan nutricional","Entrenamiento semanal","Acompa\xF1amiento continuo"],modalities:["online","presencial"],durationMinutes:null,bookingType:"integral",review:"draft",cssClass:"service-complete",symbol:"\u2726"}],programs:[{id:"impulso",title:"Impulso 8",description:"Ocho semanas para ordenar tu alimentaci\xF3n, entrenar con intenci\xF3n y convertir el esfuerzo en una rutina sostenible.",kind:"Acompa\xF1amiento",availability:"unpublished",review:"draft",serviceId:"integral",cssClass:"featured-program",featured:!0},{id:"semana",title:"Tu semana resuelta",description:"Men\xFA flexible, lista de compras y recetas simples para d\xEDas con poco tiempo.",kind:"Gu\xEDa digital",availability:"unpublished",review:"draft",serviceId:"integral",cssClass:"compact-program coral-card",featured:!1},{id:"fuerza",title:"Fuerza en casa",description:"Rutinas guiadas de 30 minutos con progresiones para cuatro semanas.",kind:"Entrenamiento",availability:"unpublished",review:"draft",serviceId:"integral",cssClass:"compact-program lime-card",featured:!1}],testimonials:[{id:"story-01",text:"Para m\xED fue un cambio de vida tu asesor\xEDa y acompa\xF1amiento. Aprend\xED a comer y a entender que debo mover y cuidar mi cuerpo para estar bien. A muchos te he recomendado porque de verdad funciona.",editorialType:"literal",attribution:"Cliente",category:"Acompa\xF1amiento integral",review:"approved",sourceReviewed:!0,publicationApproved:!0},{id:"story-02",text:"Lo mejor que pudimos hacer fue acudir juntos, en pareja, a tu asesor\xEDa. Nos motivaste un mont\xF3n durante el reto y nos llevamos much\xEDsimo aprendizaje. Eres dedicada, organizada, motivadora y, sobre todo, muy humana.",editorialType:"literal",attribution:"Pareja",category:"Reto de h\xE1bitos",review:"approved",sourceReviewed:!0,publicationApproved:!0},{id:"story-03",text:"Despu\xE9s de mi embarazo me cost\xF3 mucho volver a encontrarme conmigo misma y t\xFA me ayudaste a dar ese primer paso. Aprend\xED a mejorar mi alimentaci\xF3n y a hacer ejercicio de una forma saludable, sin obsesiones.",editorialType:"literal",attribution:"Cliente",category:"Posparto y bienestar",review:"approved",sourceReviewed:!0,publicationApproved:!0},{id:"story-04",text:"C\xF3mo porcionar un plato adecuado para una alimentaci\xF3n balanceada ya es un h\xE1bito en m\xED. Ese h\xE1bito me ha ayudado much\xEDsimo a ver cambios a largo plazo, y eso te lo debo a ti y a tus ense\xF1anzas.",editorialType:"literal",attribution:"Cliente",category:"Educaci\xF3n nutricional",review:"approved",sourceReviewed:!0,publicationApproved:!0},{id:"story-05",text:"Gracias a tu acompa\xF1amiento, tanto mi esposo como yo aprendimos a comer sano y balanceado con las porciones indicadas. Lo m\xE1s importante en mi caso es que hice del ejercicio parte de mi vida.",editorialType:"literal",attribution:"Pareja",category:"Nutrici\xF3n y movimiento",review:"approved",sourceReviewed:!0,publicationApproved:!0},{id:"story-06",text:"Gracias a ti logr\xE9 un cambio que va mucho m\xE1s all\xE1 de lo f\xEDsico. Me ense\xF1aste a entender la alimentaci\xF3n, a disfrutar comer saludable y a construir comidas equilibradas sin verlo como un castigo.",editorialType:"literal",attribution:"Cliente",category:"Cambio de h\xE1bitos",review:"approved",sourceReviewed:!0,publicationApproved:!0},{id:"story-07",text:"Al iniciar me hiciste sentir c\xF3moda y por eso volv\xED. Siempre respondiste mis dudas y nos motivabas a cumplir las rutinas. Mientras mejoraba mi f\xEDsico tambi\xE9n sent\xEDa que ganaba salud mental y una red de apoyo.",editorialType:"literal",attribution:"Cliente",category:"Entrenamiento grupal",review:"approved",sourceReviewed:!0,publicationApproved:!0},{id:"story-08",text:"Trabajar contigo siempre es muy agradable. Respetas los tiempos del entrenamiento, eres puntual y haces que las actividades se sientan muy c\xF3modas y motivadoras para seguir.",editorialType:"literal",attribution:"Cliente",category:"Entrenamiento funcional",review:"approved",sourceReviewed:!0,publicationApproved:!0},{id:"story-09",text:"Con el tiempo fui adaptando las cantidades y combinaciones hasta que se empez\xF3 a dar de forma natural. Hoy llevo nueve meses comiendo distinto, m\xE1s consciente, y los resultados han sido incre\xEDbles.",editorialType:"literal",attribution:"Cliente",category:"Plan nutricional",review:"approved",sourceReviewed:!0,publicationApproved:!0}],faqs:[{id:"faq-1",question:"\xBFNecesito experiencia entrenando?",answer:"No. Cada sesi\xF3n parte desde tu nivel actual, experiencia, movilidad y equipamiento disponible.",review:"draft"},{id:"faq-2",question:"\xBFTrabajas con dietas restrictivas?",answer:"El foco est\xE1 en sumar herramientas y construir flexibilidad. Cualquier indicaci\xF3n cl\xEDnica se adapta a tu contexto y se explica con claridad.",review:"draft"},{id:"faq-3",question:"\xBFPuedo hacer todo online?",answer:"S\xED. Consultas, seguimiento y entrenamiento pueden hacerse online con acompa\xF1amiento y material de apoyo.",review:"draft"},{id:"faq-4",question:"\xBFD\xF3nde son las sesiones presenciales?",answer:"La ubicaci\xF3n y disponibilidad presencial se confirman antes de reservar.",review:"draft"}],booking:{enabled:!0,allowedHosts:["calendly.com"],events:[{serviceId:"nutrition",modality:"online",url:"https://calendly.com/cedenorojasd/30min"},{serviceId:"nutrition",modality:"presencial",url:"https://calendly.com/cedenorojasd/30min"},{serviceId:"training",modality:"online",url:"https://calendly.com/cedenorojasd/30min"},{serviceId:"training",modality:"presencial",url:"https://calendly.com/cedenorojasd/30min"},{serviceId:"integral",modality:"online",url:"https://calendly.com/cedenorojasd/30min"},{serviceId:"integral",modality:"presencial",url:"https://calendly.com/cedenorojasd/30min"}]},publication:{origin:"",contentApproved:!1,privacyApproved:!1,bookingVerified:!1,hostingVerified:!1,reviewedOn:"",year:2026}};export{e as a};
